{"content":"/* PwShGUI · Service Cluster Dashboard · stylesheet
   VersionTag: 2604.B2.V31.0 */

:root {
  --bg-0: #0d1117;
  --bg-1: #161b22;
  --bg-2: #21262d;
  --bg-3: #2d333b;
  --fg-0: #e6edf3;
  --fg-1: #8b949e;
  --accent: #4ec9b0;
  --accent-soft: rgba(78, 201, 176, 0.18);
  --danger: #f85149;
  --warn:   #d29922;
  --ok:     #3fb950;
  --border: #30363d;
  --radius: 8px;
  --mono: 'Cascadia Code', 'Consolas', 'Courier New', monospace;
}

[data-theme="light"] {
  --bg-0: #ffffff; --bg-1: #f6f8fa; --bg-2: #eaeef2; --bg-3: #d0d7de;
  --fg-0: #1f2328; --fg-1: #59636e; --border: #d0d7de;
  --accent: #0969da; --accent-soft: rgba(9,105,218,0.12);
}

[data-theme="amber"] {
  --bg-0: #100800; --bg-1: #1a1000; --bg-2: #261800; --bg-3: #3a2400;
  --fg-0: #ffb000; --fg-1: #c08000; --accent: #ffb000;
  --accent-soft: rgba(255,176,0,0.15); --border: #4a2a00;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  font-family: 'Segoe UI', Roboto, system-ui, sans-serif;
  background: var(--bg-0); color: var(--fg-0);
  font-size: 13px;
  display: flex; flex-direction: column;
}

/* ─── Top bar ─── */
.topbar {
  display: flex; align-items: center; justify-content: space-between;
  background: var(--bg-1); border-bottom: 1px solid var(--border);
  padding: 6px 12px; gap: 12px; flex-shrink: 0;
}
.brand { display: flex; align-items: center; gap: 10px; }
.logo { font-size: 22px; color: var(--accent); }
.title { font-weight: 600; font-size: 14px; }
.title em { color: var(--accent); font-style: normal; }
.version { font-family: var(--mono); font-size: 11px; color: var(--fg-1); }

.menubar { display: flex; gap: 2px; flex: 1; justify-content: center; }
.menubar > .menu-item {
  position: relative; padding: 6px 12px; cursor: pointer; border-radius: 4px;
  user-select: none;
}
.menubar > .menu-item:hover { background: var(--bg-2); }
.menubar .submenu {
  position: absolute; top: 100%; left: 0; min-width: 240px;
  background: var(--bg-2); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 4px 0; z-index: 200;
  display: none; box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}
.menubar > .menu-item.open .submenu { display: block; }
.submenu .submenu-item {
  padding: 6px 14px; cursor: pointer; white-space: nowrap;
}
.submenu .submenu-item:hover { background: var(--accent-soft); color: var(--accent); }

.topbar-right { display: flex; align-items: center; gap: 8px; }
.status-pill {
  background: var(--bg-2); border: 1px solid var(--border);
  padding: 4px 10px; border-radius: 12px; font-size: 11px;
  font-family: var(--mono);
}
.status-pill.ok    { color: var(--ok);     border-color: var(--ok); }
.status-pill.bad   { color: var(--danger); border-color: var(--danger); }

.token-input {
  background: var(--bg-0); color: var(--fg-0); border: 1px solid var(--border);
  padding: 4px 8px; border-radius: 4px; font-family: var(--mono); width: 180px;
}

.btn {
  background: var(--bg-2); color: var(--fg-0); border: 1px solid var(--border);
  padding: 5px 12px; border-radius: 4px; cursor: pointer; font-size: 12px;
  transition: all 0.15s;
}
.btn:hover { background: var(--bg-3); border-color: var(--accent); }
.btn-primary { background: var(--accent); color: var(--bg-0); border-color: var(--accent); }
.btn-primary:hover { filter: brightness(1.1); }
.btn-success { background: var(--ok); color: #000; border-color: var(--ok); }
.btn-warn    { background: var(--warn); color: #000; border-color: var(--warn); }
.btn-danger  { background: var(--danger); color: #fff; border-color: var(--danger); }
.btn-icon { padding: 4px 8px; font-size: 14px; }

/* ─── Layout ─── */
.layout { display: flex; flex: 1; overflow: hidden; }

.blade-nav {
  width: 180px; background: var(--bg-1); border-right: 1px solid var(--border);
  display: flex; flex-direction: column; padding: 8px 4px; gap: 2px;
  overflow-y: auto;
}
.blade-tab {
  background: none; border: none; color: var(--fg-1);
  text-align: left; padding: 8px 12px; border-radius: 4px;
  cursor: pointer; font-size: 12.5px; transition: all 0.1s;
}
.blade-tab:hover { background: var(--bg-2); color: var(--fg-0); }
.blade-tab.active {
  background: var(--accent-soft); color: var(--accent);
  border-left: 2px solid var(--accent);
}

.content { flex: 1; overflow-y: auto; padding: 16px 22px; }
.blade { display: none; }
.blade.active { display: block; animation: fadeIn 0.2s; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
.blade h1 { font-size: 18px; margin-bottom: 14px; color: var(--accent); }
.blade h2 { font-size: 14px; margin: 18px 0 10px 0; color: var(--fg-0); border-bottom: 1px solid var(--border); padding-bottom: 4px; }

.metric-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 12px; margin-bottom: 20px;
}
.metric-card {
  bac[truncated]

{"filePath":"C:\PowerShellGUI\scripts\service-cluster-dashboard\static\app.js","content":"/* PwShGUI Service Cluster Dashboard frontend
   VersionTag: 2604.B2.V31.0 */

(() => {
  'use strict';

  const state = {
    token: localStorage.getItem('dash.cluster.token') || '',
    ws: null,
    wsConnected: false,
    refreshSec: Number(localStorage.getItem('dash.refresh.sec') || 3),
    menu: [],
    nodes: [],
    jobs: [],
    mcp: [],
    agents: [],
    pipeline: [],
    tools: [],
    sins: null,
  };

  const $ = (id) => document.getElementById(id);
  const fmt = {
    pct: (n) => `${Number(n || 0).toFixed(1)}%`,
    iso: (s) => s ? new Date(s).toLocaleString() : '-',
  };

  function authHeaders() {
    return state.token ? { 'X-Cluster-Token': state.token } : {};
  }

  async function api(path, opts = {}) {
    const init = { ...opts, headers: { ...(opts.headers || {}), ...authHeaders() } };
    const res = await fetch(path, init);
    if (!res.ok) {
      const text = await res.text();
      throw new Error(`${res.status} ${res.statusText} :: ${text}`);
    }
    return res.json();
  }

  function toast(msg, isErr = false) {
    const el = $('toast');
    el.textContent = msg;
    el.classList.toggle('error', isErr);
    el.classList.add('show');
    setTimeout(() => el.classList.remove('show'), 2100);
  }

  function appendLive(msg) {
    const box = $('liveLog');
    const ts = new Date().toLocaleTimeString();
    if (box.textContent.trim() === '–') box.textContent = '';
    box.textContent += `[${ts}] ${msg}\n`;
    box.scrollTop = box.scrollHeight;
  }

  function setPill(el, text, ok) {
    el.textContent = text;
    el.classList.remove('ok', 'bad');
    el.classList.add(ok ? 'ok' : 'bad');
  }

  function setBar(id, pct) {
    const p = Math.max(0, Math.min(100, Number(pct || 0)));
    $(id).style.width = `${p}%`;
  }

  function switchBlade(name) {
    document.querySelectorAll('.blade-tab').forEach((b) => b.classList.toggle('active', b.dataset.blade === name));
    document.querySelectorAll('.blade').forEach((b) => b.classList.toggle('active', b.id === `blade-${name}`));
  }

  async function loadMenu() {
    const data = await api('/api/menu/maingui');
    state.menu = data.menu || [];
    const bar = $('menuBar');
    bar.innerHTML = '';

    state.menu.forEach((top) => {
      const node = document.createElement('div');
      node.className = 'menu-item';
      node.textContent = top.label;

      const sub = document.createElement('div');
      sub.className = 'submenu';

      (top.items || []).forEach((item) => {
        const it = document.createElement('div');
        it.className = 'submenu-item';
        it.textContent = item.label;
        it.addEventListener('click', async () => {
          node.classList.remove('open');
          await invokeMenuAction(item);
        });
        sub.appendChild(it);
      });

      node.appendChild(sub);
      node.addEventListener('mouseenter', () => node.classList.add('open'));
      node.addEventListener('mouseleave', () => node.classList.remove('open'));
      node.addEventListener('click', () => node.classList.toggle('open'));
      bar.appendChild(node);
    });
  }

  async function invokeMenuAction(item) {
    if (item.action === 'system' && item.tool === 'exit') {
      showFlyout('Exit', '<p>Close this browser tab to exit dashboard view.</p>');
      return;
    }
    if (item.action === 'open_folder') {
      showFlyout('Open Folder', `<p>Requested: ${item.path}</p><p>Use workspace explorer for local folder access.</p>`);
      return;
    }
    if (item.action === 'links_category') {
      showFlyout('Links Category', `<p>Category: <strong>${item.category}</strong></p><p>This mirrors MainGUI links menu categories.</p>`);
      return;
    }
    if (item.action === 'launch' && item.tool) {
      try {
        const r = await api('/api/tools/launch', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ tool: item.tool, params: {} }),
        });
        toast(`Launched ${item.tool} (pid ${r.pid})`);
        appendLive(`Menu launch: ${item.tool} pid=${r.pid}`);
      } catch (e) {
        toast(`Launch failed: ${item.tool}`, true);
        appendLive(`Menu launch failed: ${item.tool} :: ${e.message}`);
      }
      return;
    }
    showFlyout('Menu Action', `<pre>${JSON.stringify(item, null, 2)}</pre>`);
  }

  function showFlyout(title, html) {
    $('flyoutTitle').textContent = title;
    $('flyoutBody').innerHTML = html;
    $('flyout').classList.add('open');
