        if (-not $p) { continue }
        $exists = Test-Path -LiteralPath $p
        $out.Add((Write-DiagLog -Message ("PSModulePath entry: " + $p + " (Exists=" + $exists + ")") -Level INFO))
    }

    $repos = Get-PSRepository -ErrorAction SilentlyContinue
    if (@($repos).Count -eq 0) {
