{"content":"$ErrorActionPreference = 'Stop'
$cl = Get-Content '~README.md/CHANGELOG.md' -Raw -Encoding UTF8
$lines = $cl -split "`r?`n"
$entries = @()
$cur = $null
$curSec = ''
foreach($ln in $lines){
    if($ln -match '^##\s*\[([^\]]+)\]\s*[—–-]\s*(\d{4}-\d{2}-\d{2})'){
        if($cur){ $entries += $cur }
        $cur = [ordered]@{ version=$matches[1]; date=$matches[2]; sections=[ordered]@{Added=0;Changed=0;Deprecated=0;Removed=0;Fixed=0;Security=0}; pipelineMetricsRows=0; bullets=@(); proseLines=@() }
        $curSec = ''
        continue
    }
    if(-not $cur){ continue }
    if($ln -match '^###\s*(Added|Changed|Deprecated|Removed|Fixed|Security|Pipeline Metrics)'){
        $curSec = $matches[1]
        continue
    }
    if($curSec -and $ln -match '^-\s+(.+)$'){
        if($curSec -ne 'Pipeline Metrics'){
            $cur.sections[$curSec]++
            $cur.bullets += $matches[1]
        }
        continue
    }
    if($curSec -eq 'Pipeline Metrics' -and $ln -match '^\|' -and $ln -notmatch '^\|[\s\-|]+\|$'){
        $cur.pipelineMetricsRows++
    }
}
if($cur){ $entries += $cur }

# Emoji-first detection: relevant emoji prefixes
$emojiPattern = '^[\u2620-\u3300\uD83C-\uDBFF]|^[\u2E38\u2691\u2699\u2696\u2705\u2728\u26A0\u2611\u2630-\u2638]'
# Simpler: any non-ASCII first char, or specific glyph
function HasEmojiFirst([string]$s){
    if([string]::IsNullOrWhiteSpace($s)){ return $true }
    $first = $s.TrimStart()[0]
    return [int]$first -gt 127
}

$totalScore = 0
$perEntryReport = @()
foreach($e in $entries){
    $base = 0
    foreach($k in $e.sections.Keys){ $base += $e.sections[$k] }
    $bullets = $e.bullets
    $allEmoji = $true
    foreach($b in $bullets){ if(-not (HasEmojiFirst $b)){ $allEmoji = $false; break } }
    $bonus = if($bullets.Count -gt 0 -and $allEmoji){ 1 } else { 0 }
    $final = $base + $bonus
    $totalScore += $final
    $perEntryReport += [ordered]@{
        version = $e.version
        date = $e.date
        sectionCounts = $e.sections
        bulletTotal = @($bullets).Count
        basePoints = $base
        emojiBonus = $bonus
        finalPoints = $final
    }
}

# Gap analysis: monthly contiguity 2026-01 .. 2026-04 (months covered by entries)
$dates = @($entries | ForEach-Object { [datetime]::Parse($_.date) })
$months = @($dates | ForEach-Object { '{0:yyyy-MM}' -f $_ } | Sort-Object -Unique)
$minM = [datetime]::Parse(($months | Select-Object -First 1) + '-01')
$maxM = [datetime]::Parse(($months | Select-Object -Last 1) + '-01')
$expectedMonths = @()
$m = $minM
while($m -le $maxM){ $expectedMonths += '{0:yyyy-MM}' -f $m; $m = $m.AddMonths(1) }
$gaps = @($expectedMonths | Where-Object { $_ -notin $months })
$gapPenalty = @($gaps).Count * 10
$totalScore -= $gapPenalty

$report = [ordered]@{
    generatedUtc = (Get-Date).ToUniversalTime().ToString('o')
    sourceFile = '~README.md/CHANGELOG.md'
    viewerFile = 'XHTML-ChangelogViewer.xhtml'
    entriesRestored = @($entries).Count
    monthsCovered = $months
    expectedMonths = $expectedMonths
    timelineGaps = $gaps
    gapPenalty = $gapPenalty
    inconsistencyPenalty = 0
    totalScore = $totalScore
    perEntry = $perEntryReport
}

if(-not (Test-Path '~REPORTS')){ New-Item -ItemType Directory '~REPORTS' | Out-Null }
$ts = Get-Date -Format 'yyyyMMdd-HHmmss'
$out = "~REPORTS/changelog-restoration-score-$ts.json"
$report | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $out -Encoding UTF8
"REPORT=$out"
"ENTRIES=$(@($entries).Count)"
"GAPS=$(@($gaps).Count)"
"PENALTY=$gapPenalty"
"TOTAL=$totalScore"
$perEntryReport | ForEach-Object { '{0,-22} {1}  base={2}  bonus={3}  final={4}' -f $_.version, $_.date, $_.basePoints, $_.emojiBonus, $_.finalPoints }
","filePath":"c:\PowerShellGUI\temp\score-changelog.ps1"}

