{"filePath":"c:\PowerShellGUI\XHTML-ChangelogViewer.xhtml","newString":"function loadChangelog() {
  var sel = document.getElementById('logSelect').value;
  var content = null;
  if (sel === 'CHANGELOG') { content = CHANGELOG_CONTENT; }
