  else if (typeof LOG_INDEX !== 'undefined') {
    for (var li = 0; li < LOG_INDEX.length; li++) {
      if (LOG_INDEX[li].id === sel) { content = LOG_INDEX[li].lines.join('\n'); break; }
    }
  }
  if (!content) {
    document.getElementById('browseContent').innerHTML = '<div class="empty-state"><div class="icon">⚠</div>Source not loaded.</div>';
    return;
  }
  _rawLines = content.split('\n');
  _versions = parseChangelog(_rawLines);
  populateVersionDropdowns();
  applyFilters();
  trackViewerChange(sel);
}

// Change tracker: increments on every load, persists, logs to console for test verification.
function trackViewerChange(source) {
  try {
    var k = 'cv_change_count';
    var n = parseInt(localStorage.getItem(k) || '0', 10) + 1;
    localStorage.setItem(k, String(n));
    var el = document.getElementById('changeCounter');
    if (el) { el.textContent = 'Δ:' + n; }
    // Console output for 3-cycle test verification
    console.log('[ChangelogViewer] change#' + n + ' source=' + source + ' versions=' + _versions.length + ' rawLines=' + _rawLines.length + ' ts=' + new Date().toISOString());
  } catch(e) { /* localStorage unavailable - non-fatal */ }
}

function populateLogIndexDropdown() {
  if (typeof LOG_INDEX === 'undefined') return;
  var grp = document.getElementById('logIndexGroup');
  if (!grp) return;
  grp.innerHTML = '';
  // Group by category for ordered display
  var cats = ['Pipeline','ScriptExec','AgentIter','Report'];
  for (var ci = 0; ci < cats.length; ci++) {
    for (var i = 0; i < LOG_INDEX.length; i++) {
      var it = LOG_INDEX[i];
      if (it.category !== cats[ci]) continue;
      var o = document.createElement('option');
      o.value = it.id;
      o.textContent = '[' + it.category + '] ' + it.name + ' (' + it.lineCount + 'ln, ' + it.sizeKB + 'KB)';
      grp.appendChild(o);
    }
  }
