{"command":"$ts = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffffffZ'); $stamp = (Get-Date).ToUniversalTime().ToString('yyyyMMddHHmmss'); $items = @(
  @{ id='b-find-hooks'; step='2 of 5'; title='Find service lifecycle logging hooks'; desc='Locate Start/Stop/Restart/Crash hook points in Start-Engines.ps1 and CronAiAthon-Pipeline/Scheduler modules; document call sites where per-instance text logs should be emitted.' },
  @{ id='c-implement-logs'; step='3 of 5'; title='Implement per-instance text logs'; desc='Emit one append-only text log per engine instance via Write-AppLog at lifecycle hook points (StartUp, Heartbeat, Stop, Crash). Filename pattern: logs/engine-<name>-<pid>.log.' },
  @{ id='d-integrate-checks'; step='4 of 5'; title='Integrate startup and post-mortem checks'; desc='Wire pre-start sanity check and post-mortem dump (last N log lines + exit code) into Start-Engines.ps1 and Invoke-EngineCrashCleanup.ps1.' },
  @{ id='e-verify-engine'; step='5 of 5'; title='Verify engine behaviour'; desc='Run 3-cycle start/stop/crash test, confirm per-instance logs created, post-mortem dump captured, and SIN scanner clean. Record PASS in ~REPORTS/.' }
);
foreach ($it in $items) {
  $fn = "todo\TODO-ENG-$stamp-$($it.id).json";
  $obj = [ordered]@{
    id = "TODO-ENG-$stamp-$($it.id)";
    todo_id = "TODO-ENG-$stamp-$($it.id)";
    type = 'TodoItem';
    category = 'engine-lifecycle';
    title = $it.title;
    description = $it.desc;
    priority = 'HIGH';
    status = 'OPEN';
    source_id = 'session-engine-5step';
    source_status = 'RESUMED';
    parentId = '';
    created = $ts;
    createdAt = $ts;
    modified = $ts;
    suggested_by = 'session-resume';
    file_refs = @('scripts/Start-Engines.ps1','scripts/Invoke-EngineCrashCleanup.ps1','modules/CronAiAthon-Pipeline.psm1','modules/CronAiAthon-Scheduler.psm1');
    notes = "Step $($it.step) of original 5-step engine plan (resumed from chat-only todo, never persisted). Predecessor step 1 (Compare engine scripts capabilities) completed in-conversation only.";
    status_history = @(@{ status='OPEN'; by='session-resume'; timestamp=$ts })
  };
  $obj | ConvertTo-Json -Depth 6 | Set-Content -Path $fn -Encoding UTF8;
  Write-Host "Wrote $fn"
}
