// ═══════════════════════════════════════════════════════════
// DIFF LAB — V33.5  (browser-side arbitrary-file diff + scheduler integration)
// ═══════════════════════════════════════════════════════════
var _arbL = null, _arbR = null;

function loadArbFile(side) {
  var inp = document.getElementById(side === 'L' ? 'arbLeftFile' : 'arbRightFile');
  if (!inp.files || !inp.files[0]) return;
  var f = inp.files[0];
  var rdr = new FileReader();
  rdr.onload = function(e) {
    var payload = { name: f.name, size: f.size, content: e.target.result, lines: e.target.result.split(/\r?\n/) };
    if (side === 'L') { _arbL = payload; document.getElementById('arbLeftHeader').textContent  = f.name + ' (' + f.size + ' B, ' + payload.lines.length + ' lines)'; }
    else              { _arbR = payload; document.getElementById('arbRightHeader').textContent = f.name + ' (' + f.size + ' B, ' + payload.lines.length + ' lines)'; }
  };
  rdr.readAsText(f);
}

function swapArbFiles() {
  var t = _arbL; _arbL = _arbR; _arbR = t;
  document.getElementById('arbLeftHeader').textContent  = _arbL ? _arbL.name : 'Pick a left file';
  document.getElementById('arbRightHeader').textContent = _arbR ? _arbR.name : 'Pick a right file';
  if (_arbL && _arbR) runArbDiff();
}

function runArbDiff() {
  if (!_arbL || !_arbR) { alert('Pick both files first'); return; }
  var L = _arbL.lines, R = _arbR.lines;
  var rSet = {}; for (var i = 0; i < R.length; i++) { rSet[R[i]] = (rSet[R[i]] || 0) + 1; }
  var lSet = {}; for (var j = 0; j < L.length; j++) { lSet[L[j]] = (lSet[L[j]] || 0) + 1; }
  var leftHtml = '', rightHtml = '', adds = 0, dels = 0, same = 0;
  for (var a = 0; a < L.length; a++) {
    if ((rSet[L[a]] || 0) > 0) { leftHtml += '<span class="diff-ctx">  ' + escHtml(L[a]) + '</span>'; same++; }
    else                       { leftHtml += '<span class="diff-del">- ' + escHtml(L[a]) + '</span>'; dels++; }
  }
  for (var b = 0; b < R.length; b++) {
    if ((lSet[R[b]] || 0) > 0) { rightHtml += '<span class="diff-ctx">  ' + escHtml(R[b]) + '</span>'; }
    else                       { rightHtml += '<span class="diff-add">+ ' + escHtml(R[b]) + '</span>'; adds++; }
  }
  document.getElementById('arbLeft').innerHTML  = leftHtml  || '<span class="diff-ctx">(empty)</span>';
  document.getElementById('arbRight').innerHTML = rightHtml || '<span class="diff-ctx">(empty)</span>';
  document.getElementById('arbLeftHeader').textContent  = _arbL.name + '  —  -' + dels + ' / =' + same;
  document.getElementById('arbRightHeader').textContent = _arbR.name + '  —  +' + adds + ' / =' + same;
}

function exportArbMdv() {
  if (!_arbL || !_arbR) { alert('Run a comparison first'); return; }
  var fname = 'arb-' + _arbL.name.replace(/[^A-Za-z0-9_.-]/g,'_') + '_vs_' + _arbR.name.replace(/[^A-Za-z0-9_.-]/g,'_') + '.mdv';
  var md = '<!-- Virtual Differential Markdown (Arbitrary Files) -->\n';
  md += '<!-- Generated: ' + new Date().toISOString() + ' -->\n';
  md += '<!-- Left:  ' + _arbL.name + ' (' + _arbL.size + ' B) -->\n';
